#!/usr/bin/env python3
from __future__ import annotations

import json
import shutil
from pathlib import Path


HTML = r'''<!doctype html>
<html lang="ko">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
<meta name="theme-color" content="#0b1020" />
<title>Price Structure Scanner</title>
<script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script>
<style>
:root{--bg:#070b14;--panel:#0e1526;--panel2:#121b30;--line:#24304a;--text:#e8eefb;--muted:#93a3bf;--good:#37d39a;--warn:#f7c65a;--bad:#ff6b78;--blue:#5ca8ff;--purple:#a78bfa}
*{box-sizing:border-box} body{margin:0;background:linear-gradient(180deg,#070b14,#0a1020 45%,#070b14);color:var(--text);font-family:Inter,Pretendard,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1500px;margin:auto;padding:18px}.top{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.title h1{font-size:24px;margin:0 0 6px}.title p{margin:0;color:var(--muted);font-size:13px}.actions{display:flex;flex-wrap:wrap;gap:8px}.btn,.market-link{border:1px solid var(--line);background:rgba(18,27,48,.8);color:var(--text);padding:9px 12px;border-radius:10px;text-decoration:none;font-size:13px;cursor:pointer}.btn:hover,.market-link:hover{border-color:#4a5c82}.cards{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;margin:16px 0}.card{background:rgba(14,21,38,.88);border:1px solid var(--line);border-radius:14px;padding:13px}.card .k{color:var(--muted);font-size:12px}.card .v{font-size:20px;font-weight:800;margin-top:4px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.search{min-width:240px;flex:1;background:#0d1424;border:1px solid var(--line);color:var(--text);border-radius:10px;padding:10px 12px}.select{background:#0d1424;border:1px solid var(--line);color:var(--text);border-radius:10px;padding:10px}.chips{display:flex;gap:7px;overflow:auto;padding:2px 0 10px}.chip{white-space:nowrap;border:1px solid var(--line);background:#0d1424;color:var(--muted);padding:7px 10px;border-radius:999px;cursor:pointer;font-size:12px}.chip.active{color:#fff;border-color:#5c72a7;background:#18233c}.layout{display:grid;grid-template-columns:minmax(620px,1.15fr) minmax(420px,.85fr);gap:12px}.panel{background:rgba(14,21,38,.9);border:1px solid var(--line);border-radius:14px;overflow:hidden}.panelhead{padding:12px 14px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.tablewrap{overflow:auto;max-height:76vh}table{border-collapse:collapse;width:100%;font-size:12px}th{position:sticky;top:0;background:#121b30;color:#9fb0cc;text-align:left;padding:10px 8px;border-bottom:1px solid var(--line);z-index:2;cursor:pointer}td{padding:9px 8px;border-bottom:1px solid rgba(36,48,74,.65);white-space:nowrap}tr{cursor:pointer}tr:hover{background:#131e35}.name{font-weight:750}.ticker{color:var(--muted);font-size:10px}.grade{font-weight:900}.Aplus,.A{color:var(--good)}.B{color:var(--warn)}.C,.D{color:#93a3bf}.bull{color:var(--good)}.bear{color:var(--bad)}.watch{color:var(--warn)}.pill{display:inline-block;padding:4px 7px;border:1px solid var(--line);border-radius:999px;font-size:10px}.detail{padding:14px}.hero{display:flex;justify-content:space-between;gap:10px}.hero h2{margin:0;font-size:20px}.hero .setup{margin-top:5px;font-size:13px}.scorebox{text-align:right}.scorebox strong{font-size:26px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:12px 0}.metric{background:#10192d;border:1px solid var(--line);border-radius:10px;padding:9px}.metric .k{font-size:10px;color:var(--muted)}.metric .v{font-size:13px;font-weight:700;margin-top:4px}.chart{height:410px}.sectiontitle{font-weight:800;font-size:13px;margin:14px 0 7px}.bars{display:grid;gap:7px}.barrow{display:grid;grid-template-columns:105px 1fr 38px;gap:8px;align-items:center;font-size:11px;color:var(--muted)}.bar{height:7px;border-radius:99px;background:#1d2942;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,#5ca8ff,#37d39a);border-radius:99px}.note{font-size:11px;color:var(--muted);line-height:1.55;background:#0b1221;border:1px solid var(--line);border-radius:10px;padding:10px;margin-top:12px}.empty{padding:35px;text-align:center;color:var(--muted)}
@media(max-width:1050px){.cards{grid-template-columns:repeat(3,1fr)}.layout{grid-template-columns:1fr}.tablewrap{max-height:48vh}.chart{height:360px}}
@media(max-width:600px){.wrap{padding:11px}.top{display:block}.actions{margin-top:10px}.title h1{font-size:20px}.cards{grid-template-columns:repeat(2,1fr)}.layout{display:block}.panel{margin-bottom:11px}.metrics{grid-template-columns:repeat(2,1fr)}.chart{height:320px}.tablewrap{max-height:48vh}.hide-mobile{display:none}}
</style>
</head>
<body><div class="wrap">
<div class="top"><div class="title"><h1>Price Structure Scanner</h1><p>매물대 · 지지/저항 · 추세선 · 삼각수렴 · 돌파 품질 · R/R 기반 차트 구조 분석</p></div><div class="actions"><a class="market-link" href="../">한국 지표</a><a class="market-link" href="../us/">미국 시장</a><a class="market-link" href="../position/">포지션 관리</a><button class="btn" onclick="location.reload()">새로고침</button></div></div>
<div class="cards" id="cards"></div>
<div class="toolbar"><input id="search" class="search" placeholder="종목명 또는 코드 검색"/><select id="market" class="select"><option value="ALL">전체 시장</option><option>KOSPI</option><option>KOSDAQ</option></select><select id="grade" class="select"><option value="ALL">전체 등급</option><option>A+</option><option>A</option><option>B</option><option>C</option><option>D</option></select><select id="sort" class="select"><option value="score">점수순</option><option value="rr1">R/R순</option><option value="breakout_quality">돌파품질순</option><option value="rvol">RVOL순</option><option value="rs_score">상대강도순</option></select></div>
<div class="chips" id="chips"></div>
<div class="layout"><section class="panel"><div class="panelhead"><strong>종목 스캔</strong><span id="count" style="color:var(--muted);font-size:11px"></span></div><div class="tablewrap"><table><thead><tr><th>종목</th><th>등급</th><th>셋업</th><th>점수</th><th>구조</th><th>R/R</th><th>RVOL</th><th class="hide-mobile">돌파품질</th><th class="hide-mobile">RS</th></tr></thead><tbody id="tbody"></tbody></table></div></section><section class="panel" id="detailPanel"><div class="empty">왼쪽에서 종목을 선택하세요.</div></section></div>
<div class="note">이 페이지의 Volume Profile은 일봉 OHLCV를 가격 구간에 분배해 근사한 값입니다. 실제 체결가별 Volume-at-Price와는 다를 수 있습니다. Pivot은 오른쪽 확인 봉이 완성된 이후에만 확정하여 미래 데이터 사용을 피하도록 설계했습니다. 등급은 매수 명령이 아니라 셋업의 구조적 품질을 뜻합니다.</div>
</div>
<script>
let DATA=[], FILTER='ALL', selectedTicker=null;
const SETUPS=['ALL','BREAKOUT_READY','CONFIRMED_BREAKOUT','TRENDLINE_BREAKOUT','TRIANGLE_BREAKOUT','RETEST_ENTRY','SUPPORT_BOUNCE','FAILED_BREAKOUT','SUPPORT_BREAKDOWN','COMPRESSION_WATCH'];
const labels={ALL:'전체',BREAKOUT_READY:'⚡ 돌파 임박',CONFIRMED_BREAKOUT:'🔥 저항 돌파',TRENDLINE_BREAKOUT:'↗ 추세선 돌파',TRIANGLE_BREAKOUT:'△ 삼각 돌파',RETEST_ENTRY:'✓ 리테스트',SUPPORT_BOUNCE:'🛡 지지 반등',FAILED_BREAKOUT:'⚠ 실패 돌파',SUPPORT_BREAKDOWN:'↓ 지지 이탈',COMPRESSION_WATCH:'◇ 수렴 관찰'};
function n(v,d=1){return v==null||Number.isNaN(+v)?'-':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:d})} function pct(v){return v==null?'-':(v*100).toFixed(1)+'%'}
function setupClass(r){return r.direction==='BULLISH'?'bull':r.direction==='BEARISH'?'bear':'watch'}
function initChips(){document.getElementById('chips').innerHTML=SETUPS.map(x=>`<button class="chip ${x==='ALL'?'active':''}" data-x="${x}">${labels[x]||x}</button>`).join('');document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{FILTER=b.dataset.x;document.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active',x===b));render();});}
function cards(meta){const rows=meta.rows||[];const c=[['분석 종목',rows.length],['A+ / A',rows.filter(x=>x.grade==='A+'||x.grade==='A').length],['Hard Filter',rows.filter(x=>x.hard_filter_pass).length],['돌파 임박',rows.filter(x=>x.setup==='BREAKOUT_READY').length],['확정 돌파',rows.filter(x=>['CONFIRMED_BREAKOUT','TRENDLINE_BREAKOUT','TRIANGLE_BREAKOUT'].includes(x.setup)).length],['Risk / 실패',rows.filter(x=>['FAILED_BREAKOUT','SUPPORT_BREAKDOWN','TRENDLINE_BREAKDOWN','TRIANGLE_BREAKDOWN'].includes(x.setup)).length]];document.getElementById('cards').innerHTML=c.map(x=>`<div class="card"><div class="k">${x[0]}</div><div class="v">${x[1]}</div></div>`).join('')}
function filtered(){const q=document.getElementById('search').value.trim().toLowerCase(),m=document.getElementById('market').value,g=document.getElementById('grade').value,s=document.getElementById('sort').value;let a=DATA.filter(r=>(!q||r.name.toLowerCase().includes(q)||r.ticker.includes(q))&&(m==='ALL'||r.market===m)&&(g==='ALL'||r.grade===g)&&(FILTER==='ALL'||r.setup===FILTER));a.sort((x,y)=>(Number(y[s])||-999)-(Number(x[s])||-999));return a}
function render(){const a=filtered();document.getElementById('count').textContent=`${a.length}개`;document.getElementById('tbody').innerHTML=a.map(r=>`<tr data-t="${r.ticker}"><td><div class="name">${r.name}</div><div class="ticker">${r.ticker} · ${r.market}</div></td><td class="grade ${r.grade==='A+'?'Aplus':r.grade}">${r.grade}${r.hard_filter_pass?' ✓':''}</td><td class="${setupClass(r)}"><span class="pill">${r.setup_label}</span></td><td><b>${n(r.score)}</b></td><td>${r.structure_code}</td><td>${n(r.rr1,2)}</td><td>${n(r.rvol,2)}</td><td class="hide-mobile">${n(r.breakout_quality)}</td><td class="hide-mobile">${n(r.rs_score)}</td></tr>`).join('');document.querySelectorAll('#tbody tr').forEach(tr=>tr.onclick=()=>loadDetail(tr.dataset.t));}
async function loadDetail(t){selectedTicker=t;const p=document.getElementById('detailPanel');p.innerHTML='<div class="empty">불러오는 중...</div>';try{const d=await fetch(`data/details/${t}.json?ts=${Date.now()}`).then(r=>r.json());showDetail(d)}catch(e){p.innerHTML='<div class="empty">상세 데이터를 불러오지 못했습니다.</div>'}}
function metric(k,v,cls=''){return `<div class="metric"><div class="k">${k}</div><div class="v ${cls}">${v}</div></div>`}
function showDetail(d){const a=d.analysis,m=d.meta,b=a.breakout_quality||{},tr=a.trade||{},tri=a.triangle||{},rs=a.relative_strength||{},sup=a.support||{},res=a.resistance||{};const comps=b.components||{};document.getElementById('detailPanel').innerHTML=`<div class="detail"><div class="hero"><div><h2>${m.name} <span style="color:var(--muted);font-size:12px">${m.ticker}</span></h2><div class="setup ${a.direction==='BULLISH'?'bull':a.direction==='BEARISH'?'bear':'watch'}">${a.setup_label}</div></div><div class="scorebox"><strong class="${a.grade==='A+'?'Aplus':a.grade}">${a.grade}</strong><div>${n(a.score)} / 100</div></div></div><div class="metrics">${metric('현재가',n(a.price,0))}${metric('시장 구조',a.structure.code)}${metric('Breakout Quality',n(b.score))}${metric('RVOL',n(b.rvol,2))}${metric('20D 초과수익',pct(rs.excess_return))}${metric('R/R 1',n(tr.rr1,2),tr.rr1>=1.8?'bull':'')}${metric('지지 구간',sup.low?`${n(sup.low,0)} ~ ${n(sup.high,0)}`:'-')}${metric('저항 구간',res.low?`${n(res.low,0)} ~ ${n(res.high,0)}`:'-')}${metric('삼각수렴',tri.label||'-')}</div><div id="chart" class="chart"></div><div class="sectiontitle">Breakout Quality 구성</div><div class="bars">${Object.entries(comps).map(([k,v])=>`<div class="barrow"><span>${k}</span><div class="bar"><i style="width:${Math.min(100,v/20*100)}%"></i></div><b>${n(v)}</b></div>`).join('')}</div><div class="sectiontitle">Trade Structure</div><div class="metrics">${metric('Entry',n(tr.entry,0))}${metric('Stop / Invalidation',n(tr.stop,0))}${metric('Target 1',n(tr.target1,0))}${metric('Target 2',n(tr.target2,0))}${metric('Risk (ATR)',n(tr.risk_atr,2))}${metric('Hard Filter',a.hard_filter_pass?'PASS':'WATCH',a.hard_filter_pass?'bull':'watch')}</div></div>`;drawChart(a.chart,m.name)}
function drawChart(c,name){if(!c||!c.bars)return;const bars=c.bars,dates=bars.map(x=>x.date);const trace={type:'candlestick',x:dates,open:bars.map(x=>x.open),high:bars.map(x=>x.high),low:bars.map(x=>x.low),close:bars.map(x=>x.close),name:name,increasing:{line:{color:'#37d39a'}},decreasing:{line:{color:'#ff6b78'}}};const shapes=[];const ann=[];const x0=dates[0],x1=dates[dates.length-1];function zone(z,color,label){if(!z)return;shapes.push({type:'rect',xref:'x',yref:'y',x0:x0,x1:x1,y0:z.low,y1:z.high,fillcolor:color,opacity:.10,line:{width:1,color:color}});ann.push({x:x1,y:z.center,text:label,showarrow:false,xanchor:'right',font:{size:10,color:color}})}zone(c.support,'#37d39a','SUPPORT');zone(c.resistance,'#ff6b78','RESIST');if(c.poc)shapes.push({type:'line',xref:'x',yref:'y',x0:x0,x1:x1,y0:c.poc,y1:c.poc,line:{color:'#a78bfa',width:1,dash:'dot'}});function trend(l,color){if(!l)return;const b0=bars.find(b=>b.x>=l.x0)||bars[0],b1=bars.find(b=>b.x>=l.x1)||bars[bars.length-1];shapes.push({type:'line',xref:'x',yref:'y',x0:b0.date,x1:b1.date,y0:l.y0,y1:l.y1,line:{color:color,width:2}})}trend(c.descending_trendline,'#f7c65a');trend(c.ascending_trendline,'#5ca8ff');if(c.triangle){trend(c.triangle.upper,'#f7c65a');trend(c.triangle.lower,'#5ca8ff')}Plotly.newPlot('chart',[trace],{paper_bgcolor:'transparent',plot_bgcolor:'transparent',font:{color:'#93a3bf'},margin:{l:45,r:25,t:15,b:35},xaxis:{rangeslider:{visible:false},gridcolor:'#18233a'},yaxis:{gridcolor:'#18233a',side:'right'},shapes:shapes,annotations:ann,showlegend:false},{displayModeBar:false,responsive:true})}
['search','market','grade','sort'].forEach(id=>document.getElementById(id).addEventListener(id==='search'?'input':'change',render));initChips();fetch(`data/summary.json?ts=${Date.now()}`).then(r=>r.json()).then(meta=>{DATA=meta.rows||[];cards(meta);render();if(DATA.length)loadDetail(DATA[0].ticker)}).catch(()=>document.getElementById('tbody').innerHTML='<tr><td colspan="9">summary.json을 불러오지 못했습니다.</td></tr>');
</script></body></html>'''


def main() -> None:
    src = Path("price_structure_results")
    if not (src / "summary.json").exists():
        raise SystemExit("price_structure_results/summary.json not found. Run price_structure_scanner.py first.")
    dst = Path("docs/price-structure")
    data = dst / "data"
    details = data / "details"
    details.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src / "summary.json", data / "summary.json")
    if (src / "summary.csv").exists():
        shutil.copy2(src / "summary.csv", data / "summary.csv")
    for p in (src / "details").glob("*.json"):
        shutil.copy2(p, details / p.name)
    (dst / "index.html").write_text(HTML, encoding="utf-8")
    print(f"Built {dst / 'index.html'}")


if __name__ == "__main__":
    main()
